import React, { Component } from 'react';
import { Card, Table, Icon, Button, Spin, Alert, Input, Dropdown, Menu, Modal, message } from 'antd';
import { getInstance } from 'd2/lib/d2';
import PropTypes from 'prop-types';

const { Search } = Input;

class ProgramsHierarchyList extends Component {
    constructor(props) {
        super(props);
        this.state = {
            programs: [], // Level 3 organization units (programs)
            loading: false,
            error: null,
            searchValue: '',
            filteredPrograms: [],
            deletingProgramId: null // Track which program is being deleted
        };
        this._isMounted = false;
    }

    componentDidMount() {
        this._isMounted = true;
        this.fetchPrograms();
    }

    componentWillUnmount() {
        this._isMounted = false;
    }

    fetchPrograms = async () => {
        if (!this._isMounted) return;

        this.setState({ loading: true, error: null });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            const data = await api.get('organisationUnits', {
                level: 3,
                paging: false,
                fields: 'id,displayName,openingDate,parent[id,displayName,parent[id,displayName]]'
            });

            if (this._isMounted) {
                this.setState({
                    programs: data.organisationUnits || [],
                    filteredPrograms: data.organisationUnits || [],
                    loading: false
                });
            }
        } catch (error) {
            console.error('Error fetching programs:', error);
            if (this._isMounted) {
                this.setState({
                    error: 'Failed to fetch programs. Please try again.',
                    loading: false
                });
            }
        }
    };

    handleProgramEdit = (program) => {
        // Navigate to custom edit program page
        const redirectUrl = `/sims-web-maintenance/#/edit-program/${program.id}`;
        window.location.href = redirectUrl;
    };

    handleProgramDelete = (program) => {
        Modal.confirm({
            title: 'Delete Program',
            content: (
                <div>
                    <p>Are you sure you want to delete the program <strong>"{program.displayName}"</strong>?</p>
                    <p style={{ color: '#ff4d4f', marginBottom: 0 }}>This action will also delete all associated projects. This cannot be undone.</p>
                </div>
            ),
            okText: 'Delete',
            okType: 'danger',
            cancelText: 'Cancel',
            width: 450,
            onOk: () => {
                return this.deleteProgram(program.id);
            },
        });
    };

    deleteProgram = async (programId) => {
        this.setState({ deletingProgramId: programId });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            await api.delete(`organisationUnits/${programId}`);

            // Remove the deleted program from state
            const updatedPrograms = this.state.programs.filter(program => program.id !== programId);
            const updatedFilteredPrograms = this.state.filteredPrograms.filter(program => program.id !== programId);

            this.setState({
                programs: updatedPrograms,
                filteredPrograms: updatedFilteredPrograms,
                deletingProgramId: null
            });

            message.success('Program deleted successfully');
        } catch (error) {
            console.error('Error deleting program:', error);
            this.setState({ deletingProgramId: null });

            Modal.error({
                title: 'Delete Failed',
                content: `Failed to delete the program: ${error.message}`,
            });
        }
    };

    handleCreateProgram = () => {
        // Navigate to create new program page
        const redirectUrl = `/sims-web-maintenance/#/create-program`;
        window.location.href = redirectUrl;
    };

    // Get more actions menu for programs
    getProgramActionsMenu = (program) => {
        const { deletingProgramId } = this.state;
        const isDeleting = deletingProgramId === program.id;

        return (
            <Menu>
                <Menu.Item key="edit" onClick={() => this.handleProgramEdit(program)}>
                    <Icon type="edit" style={{ marginRight: '8px' }} />
                    Edit Program
                </Menu.Item>
                <Menu.Divider />
                <Menu.Item
                    key="delete"
                    onClick={() => this.handleProgramDelete(program)}
                    disabled={isDeleting}
                    style={{ color: isDeleting ? '#ccc' : '#ff4d4f' }}
                >
                    <Icon type={isDeleting ? "loading" : "delete"} style={{ marginRight: '8px' }} />
                    {isDeleting ? 'Deleting...' : 'Delete Program'}
                </Menu.Item>
            </Menu>
        );
    };

    handleSearch = (value) => {
        const { programs } = this.state;

        if (!value.trim()) {
            this.setState({
                searchValue: value,
                filteredPrograms: programs
            });
            return;
        }

        const searchTerm = value.toLowerCase();
        const filteredPrograms = programs.filter(program => {
            // Search in program name, ID
            const programMatches = program.displayName.toLowerCase().includes(searchTerm) ||
                program.id.toLowerCase().includes(searchTerm)

            // Search in parent thematic area
            const thematicAreaMatches = program.parent &&
                program.parent.displayName.toLowerCase().includes(searchTerm);

            // Search in grandparent (if exists)
            const grandParentMatches = program.parent && program.parent.parent &&
                program.parent.parent.displayName.toLowerCase().includes(searchTerm);

            return programMatches || thematicAreaMatches || grandParentMatches;
        });

        this.setState({
            searchValue: value,
            filteredPrograms: filteredPrograms
        });
    };

    render() {
        const { programs, loading, error, searchValue, filteredPrograms } = this.state;

        const cardStyle = {
            margin: '20px auto',
            maxWidth: '1200px',
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
        };

        const headerStyle = {
            padding: '24px',
            borderRadius: '8px 8px 0 0',
        };

        if (loading) {
            return (
                <Card style={cardStyle}>
                    <div style={{ textAlign: 'center', padding: '60px 0' }}>
                        <Spin size="large" />
                        <div style={{ marginTop: '16px', fontSize: '16px', color: '#666' }}>
                            Loading programs...
                        </div>
                    </div>
                </Card>
            );
        }

        if (error) {
            return (
                <Card style={cardStyle}>
                    <div style={{ padding: '40px' }}>
                        <Alert
                            message="Error Loading Data"
                            description={error}
                            type="error"
                            showIcon
                            action={
                                <Button size="small" type="primary" onClick={this.fetchPrograms}>
                                    Try Again
                                </Button>
                            }
                        />
                    </div>
                </Card>
            );
        }

        const columns = [
            {
                title: 'Program Name',
                dataIndex: 'displayName',
                key: 'displayName',
                render: (text, program) => {
                    let displayText = text;
                    if (searchValue && searchValue.trim()) {
                        const searchTerm = searchValue.toLowerCase();
                        if (text.toLowerCase().includes(searchTerm)) {
                            const regex = new RegExp(`(${searchValue})`, 'gi');
                            displayText = text.replace(regex, '<mark>$1</mark>');
                        }
                    }

                    return (
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <Icon type="project" style={{ color: '#fa8c16', marginRight: '8px', fontSize: '16px' }} />
                            <span
                                style={{ fontWeight: '500', fontSize: '16px' }}
                                dangerouslySetInnerHTML={{ __html: displayText }}
                            />
                        </div>
                    );
                }
            },
            {
                title: 'Thematic Area',
                dataIndex: 'parent',
                key: 'parent',
                render: (parent) => {
                    if (!parent) {
                        return <span style={{ color: '#999', fontStyle: 'italic' }}>No thematic area</span>;
                    }

                    let displayText = parent.displayName;
                    if (searchValue && searchValue.trim()) {
                        const searchTerm = searchValue.toLowerCase();
                        if (parent.displayName.toLowerCase().includes(searchTerm)) {
                            const regex = new RegExp(`(${searchValue})`, 'gi');
                            displayText = parent.displayName.replace(regex, '<mark>$1</mark>');
                        }
                    }

                    return (
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <Icon type="folder" style={{ color: '#1890ff', marginRight: '8px' }} />
                            <span dangerouslySetInnerHTML={{ __html: displayText }} />
                        </div>
                    );
                }
            },
            {
                title: 'Created Date',
                dataIndex: 'openingDate',
                key: 'openingDate',
                width: 120,
                render: (date) => {
                    if (!date) return <span style={{ color: '#999', fontStyle: 'italic' }}>Unknown</span>;
                    return new Date(date).toLocaleDateString();
                }
            },
            {
                title: 'Actions',
                key: 'actions',
                width: 120,
                render: (text, program) => (
                    <Dropdown
                        overlay={this.getProgramActionsMenu(program)}
                        trigger={['click']}
                        placement="bottomRight"
                    >
                        <Button size="small" icon="more">
                        </Button>
                    </Dropdown>
                )
            }
        ];

        const dataSource = searchValue ? filteredPrograms : programs;

        return (
            <div>
                <Card bodyStyle={{ padding: 0 }}>
                    {/* Header */}
                    <div style={headerStyle}>
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <div>
                                <h1 style={{
                                    margin: 0,
                                    fontSize: '24px',
                                    fontWeight: 'bold',
                                }}>
                                    Programs
                                </h1>
                                <p style={{ margin: '8px 0 0 0', color: '#666' }}>
                                    Manage all programs
                                </p>
                            </div>
                        </div>
                    </div>

                    {/* Table Content */}
                    <div style={{ padding: '0 24px 24px 24px' }}>
                        {programs.length === 0 ? (
                            <div style={{ textAlign: 'center', padding: '60px 0', color: '#999' }}>
                                <Icon type="project" style={{ fontSize: '64px', color: '#d9d9d9', marginBottom: '16px' }} />
                                <div style={{ fontSize: '16px' }}>No programs found</div>
                                <div style={{ fontSize: '14px', marginTop: '8px' }}>
                                    <Button type="primary" onClick={this.handleCreateProgram} style={{ marginTop: '16px' }}>
                                        <Icon type="plus" />
                                        Create Your First Program
                                    </Button>
                                </div>
                            </div>
                        ) : (
                            <div>
                                <Search
                                    placeholder="Search programs by name or thematic area"
                                    value={searchValue}
                                    onChange={(e) => this.handleSearch(e.target.value)}
                                    style={{ width: 500, marginBottom: 16 }}
                                />
                                {searchValue && (
                                    <div style={{ marginBottom: 16, color: '#666', fontSize: '14px' }}>
                                        <Icon type="search" style={{ marginRight: '4px' }} />
                                        Found {dataSource.length} program(s) for "{searchValue}"
                                    </div>
                                )}
                                <Table
                                    columns={columns}
                                    dataSource={dataSource}
                                    rowKey="id"
                                    pagination={{
                                        pageSize: 10,
                                        showSizeChanger: true,
                                        showQuickJumper: true,
                                        showTotal: (total, range) =>
                                            `${range[0]}-${range[1]} of ${total} ${searchValue ? 'filtered' : ''} programs`,
                                    }}
                                    size="middle"
                                />
                            </div>
                        )}
                    </div>
                </Card>

                {/* Floating Add Button */}
                <div style={{
                    position: 'fixed',
                    bottom: '24px',
                    right: '24px',
                    zIndex: 1000
                }}>
                    <Button
                        type="primary"
                        size="large"
                        shape="circle"
                        icon="plus"
                        onClick={this.handleCreateProgram}
                        style={{
                            width: '56px',
                            height: '56px',
                            fontSize: '20px',
                            boxShadow: '0 4px 12px rgba(24, 144, 255, 0.3)',
                            border: 'none'
                        }}
                        title="Add New Program"
                    />
                </div>
            </div>
        );
    }
}

ProgramsHierarchyList.contextTypes = {
    d2: PropTypes.object
};

export default ProgramsHierarchyList;



